def lin(c):
    c = c / 255.0
    return c / 12.92 if c <= 0.03928 else ((c + 0.055) / 1.055) ** 2.4


def L(hexs):
    r = int(hexs[1:3], 16)
    g = int(hexs[3:5], 16)
    b = int(hexs[5:7], 16)
    return 0.2126 * lin(r) + 0.7152 * lin(g) + 0.0722 * lin(b)


def ratio(a, b):
    la, lb = L(a), L(b)
    hi, lo = max(la, lb), min(la, lb)
    return (hi + 0.05) / (lo + 0.05)


faces = {
    'page': '#0f1626',
    'digit': '#303a5c',
    'operator': '#f0a02a',
    'action': '#4fc78a',
    'equals': '#37d98a',
    'display': '#1b2440',
}

inner = '#05070d'
outer = '#f5f7fa'
print('inner-vs-outer ring:', round(ratio(inner, outer), 2))
